items.syntax:
awk -F<sep> '$<host-field>=="<host>" && $<result-field>=="<result>" {
  if ($<value-field> > <threshold>) { if (++run == 1) first = $<ts-field>; if (run == <run-length>) { print first; exit } } else run = 0
}' <csv-file>

items.command:
awk -F, '$2=="bench-02" && $4=="ok" {
  if ($6 > 300) { if (++run == 1) first = $1; if (run == 6) { print first; exit } } else run = 0
}' perf/sshd-auth-timing.csv

items.syntaxPowershell:
$run = 0; $first = $null
foreach ($r in Import-Csv .\<csv-file> | Where-Object { $_.<host-column> -eq '<host>' -and $_.<result-column> -eq '<result>' }) {
  if ([int]$r.<value-column> -gt <threshold>) { $run++; if ($run -eq 1) { $first = $r.<epoch-column> }; if ($run -eq <run-length>) { $first; break } } else { $run = 0 } }

items.powershell:
$run = 0; $first = $null
foreach ($r in Import-Csv .\perf\sshd-auth-timing.csv | Where-Object { $_.host -eq 'bench-02' -and $_.result -eq 'ok' }) {
  if ([int]$r.auth_ms -gt 300) { $run++; if ($run -eq 1) { $first = $r.ts_epoch }; if ($run -eq 6) { $first; break } } else { $run = 0 } }

items.syntaxPowershell:
Import-Csv .\<csv-file> | Where-Object <result-column> -eq '<result>' |
  Group-Object <host-column>, { [math]::Floor([long]$_.<epoch-column> / <seconds-per-day>) } |
  ForEach-Object { '{0} avg={1:N0}' -f $_.Name, ($_.Group | Measure-Object <value-column> -Average).Average }

items.powershell:
Import-Csv .\perf\sshd-auth-timing.csv | Where-Object result -eq 'ok' |
  Group-Object host, { [math]::Floor([long]$_.ts_epoch / 86400) } |
  ForEach-Object { '{0} avg={1:N0}' -f $_.Name, ($_.Group | Measure-Object auth_ms -Average).Average }

items.syntaxPowershell:
$prev = ''
$(foreach ($l in Get-Content .\<diff-file>) {
  if ($l -like '<new-header-pattern>' -and $prev -like '<old-header-pattern>') { ($l -split '\s+')[<index>] -replace '<prefix-regex>', '' }
  $prev = $l }) | Group-Object | Sort-Object Count | Select-Object -First <n> Count, Name

items.powershell:
$prev = ''
$(foreach ($l in Get-Content .\release\tarball-vs-git-tag.diff) {
  if ($l -like '+++ *' -and $prev -like '--- *1970-01-01*') { ($l -split '\s+')[1] -replace '^[^/]*/', '' }
  $prev = $l }) | Group-Object | Sort-Object Count | Select-Object -First 10 Count, Name

$f = 'm4/<name>.m4'; $on = $false
foreach ($l in Get-Content .\release\tarball-vs-git-tag.diff) {
  if ($l -match '^(diff -ruN|Binary files|######## )') { $on = $l.Contains("/$f ") }
  if ($on) { $l } }

items.syntaxPowershell:
$sha = ''; $d = ''
foreach ($l in Get-Content .\<git-log-export>) {
  if ($l -match '<commit-line-regex>') { $sha = $matches[1] }
  elseif ($l -match '<date-line-regex>') { $d = $matches[1] }
  elseif ($l -match '<file-header-regex>') { "$sha $d $($matches[1])" } }

items.powershell:
$sha = ''; $d = ''
foreach ($l in Get-Content .\repo\git-log.txt) {
  if ($l -match '^commit ([0-9a-f]{7})') { $sha = $matches[1] }
  elseif ($l -match '^Date:\s+(\S+ \S+)') { $d = $matches[1] }
  elseif ($l -match '^diff --git a/tests/files/\S+ b/(\S+)') { "$sha $d $($matches[1])" } }

items.syntaxPowershell:
$f = '<path>'; $sha = ''; $d = ''; $p = ''
foreach ($l in Get-Content .\<git-log-export>) {
  if ($l -match '<commit-line-regex>') { $sha = $matches[1] }
  elseif ($l -match '<date-line-regex>') { $d = $matches[1] }
  elseif ($l -match '<file-header-regex>') { $p = $matches[1] }
  elseif ($l -like '<added-marker>*' -and $p -eq $f) { "$sha $d $p" } }

items.powershell:
$f = 'tests/files/<file>'; $sha = ''; $d = ''; $p = ''
foreach ($l in Get-Content .\repo\git-log.txt) {
  if ($l -match '^commit ([0-9a-f]{7})') { $sha = $matches[1] }
  elseif ($l -match '^Date:\s+(\S+ \S+)') { $d = $matches[1] }
  elseif ($l -match '^diff --git \S+ b/(\S+)') { $p = $matches[1] }
  elseif ($l -like 'new file mode*' -and $p -eq $f) { "$sha $d $p" } }

# example range: libsdnotify. Paste another library's Start and End.
$lo = [Convert]::ToInt64('0x00007f3a9c100000', 16); $hi = [Convert]::ToInt64('0x00007f3a9c10c000', 16)
Get-Content .\perf\gdb-got-audit.txt | Where-Object { $_ -match '^0x[0-9a-f]+\s+\S+\s+0x' } | ForEach-Object {
  $f = $_ -split '\s+'; $t = [Convert]::ToInt64($f[2], 16); if ($t -ge $lo -and $t -lt $hi) { "$($f[1]) -> $($f[2])" } }
